 Future<void> load()async{final p=await SharedPreferences.getInstance();try{filaments=(jsonDecode(p.getString('filaments')??'[]') as List).map((x)=>Filament(x['name'] as String,(x['price'] as num).toDouble())).toList();}catch(_){filaments=[];}energy.text=p.getString('energy')??'0,15';power.text=p.getString('power')??'200';english=p.getBool('english')??false;if(filaments.isNotEmpty)selected=filaments.first.name;if(mounted)setState((){});}
